insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e45', null, 'Seated Dumbbell Curl', 'Biceps', '{}'::text[], 'Dumbbells', 'Sit upright on a bench with a dumbbell in each hand. Curl both arms without swinging your torso. Lower slowly to full extension.', false) on conflict (id) do nothing;
