insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e47', null, 'Concentration Curl', 'Biceps', '{}'::text[], 'Dumbbells', 'Sit and brace your elbow against the inside of your thigh. Curl the dumbbell to your shoulder, squeezing at the top. Lower under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e48', null, 'Spider Curl', 'Biceps', '{}'::text[], 'Dumbbells', 'Lie chest-down on an incline bench with your arms hanging straight down. Curl without moving your upper arms. Lower to full extension.', false) on conflict (id) do nothing;
