insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e50', null, 'Reverse Curl', 'Forearms', array['Biceps']::text[], 'Barbell', 'Grip the bar pronated at shoulder width. Curl with your wrists locked straight. Lower under control.', false) on conflict (id) do nothing;
