insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e52', null, 'Wrist Curl', 'Forearms', '{}'::text[], 'Dumbbells', 'Rest your forearms on a bench with your wrists past the edge, palms up. Curl your wrists as far as comfortable. Lower slowly for the stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e53', null, 'Cable Overhead Triceps Extension', 'Triceps', '{}'::text[], 'Cable', 'Face away from the pulley with the rope behind your head. Extend your elbows overhead. Return to a deep stretch under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e54', null, 'Close-Grip Bench Press', 'Triceps', array['Chest']::text[], 'Barbell', 'Grip the bar just inside shoulder width and keep your elbows tucked. Lower to the lower chest. Press up, driving with the triceps.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e55', null, 'Triceps Dip', 'Triceps', array['Chest']::text[], 'Bodyweight', 'Support yourself on parallel bars with your torso upright. Lower until your elbows reach 90 degrees. Press back up without shrugging.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e56', null, 'Single-Arm Cable Kickback', 'Triceps', '{}'::text[], 'Cable', 'Lean forward with your upper arm parallel to the floor. Extend your elbow fully back. Return slowly, keeping the shoulder still.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e57', null, 'Straight-Arm Pulldown', 'Back', '{}'::text[], 'Cable', 'Stand facing the high pulley with straight arms and a slight forward lean. Pull down to your thighs using the lats only. Return under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e58', null, 'T-Bar Row', 'Back', array['Biceps']::text[], 'Machine', 'Straddle the bar with a neutral spine and hinged torso. Pull the handles to your lower ribs. Lower to a full lat stretch.', false) on conflict (id) do nothing;
