insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e61', null, 'Neutral-Grip Pulldown', 'Back', '{}'::text[], 'Cable', 'Use a close neutral handle with your thighs locked under the pad. Pull to your upper chest, driving your elbows down. Return without shrugging.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e62', null, 'Machine Chest Press', 'Chest', array['Triceps']::text[], 'Machine', 'Set the seat so the handles line up with your mid-chest. Press until your arms are nearly straight. Return under control to a chest stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e63', null, 'Dumbbell Bench Press', 'Chest', array['Triceps']::text[], 'Dumbbells', 'Lie flat with the dumbbells at chest height and wrists stacked. Press up without clashing the dumbbells. Lower until you feel the chest stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e64', null, 'Incline Barbell Press', 'Chest', array['Shoulders']::text[], 'Barbell', 'Set the bench to about 30 degrees and grip just outside shoulder width. Lower to the upper chest. Press without letting your elbows flare wide.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e65', null, 'Dumbbell Fly', 'Chest', '{}'::text[], 'Dumbbells', 'Lie flat with your arms wide and elbows softly bent. Open until you feel a chest stretch. Bring the dumbbells together in an arc.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e66', null, 'Cable Lateral Raise', 'Shoulders', '{}'::text[], 'Cable', 'Stand side-on to a low pulley with the handle in the far hand. Raise your arm to shoulder height. Lower slowly against the cable.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e67', null, 'Machine Lateral Raise', 'Shoulders', '{}'::text[], 'Machine', 'Sit with the pads against your outer arms. Raise to shoulder height, leading with the elbows. Lower over two seconds.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e68', null, 'Arnold Press', 'Shoulders', array['Triceps']::text[], 'Dumbbells', 'Start with the dumbbells in front at chin height, palms in. Rotate out while pressing overhead. Reverse the path on the way down.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e69', null, 'Face Pull', 'Shoulders', array['Traps']::text[], 'Cable', 'Set the pulley at face height and hold the rope with thumbs back. Pull toward your forehead, opening your elbows wide. Return under control.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e70', null, 'Barbell Shrug', 'Traps', '{}'::text[], 'Barbell', 'Hold the bar at arms'' length in front of your thighs. Shrug straight up toward your ears. Lower to a full trap stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e71', null, 'Smith Machine Squat', 'Quads', array['Glutes']::text[], 'Machine', 'Set the bar on your upper back with feet slightly forward. Lower until your thighs break parallel. Press up through mid-foot.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e72', null, 'Belt Squat', 'Quads', array['Glutes']::text[], 'Machine', 'Attach the belt at your hips and stand tall on the platform. Lower under control with an upright torso. Drive up without leaning forward.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e73', null, 'Walking Lunge', 'Quads', array['Glutes', 'Hamstrings']::text[], 'Dumbbells', 'Hold dumbbells at your sides and step forward into a lunge. Lower until your back knee nearly touches the floor. Step through into the next rep.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e74', null, 'Nordic Hamstring Curl', 'Hamstrings', array['Core']::text[], 'Bodyweight', 'Kneel with your ankles anchored and your body straight. Lower forward as slowly as you can control. Push off lightly and pull yourself back up.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e75', null, 'Good Morning', 'Hamstrings', array['Lower back', 'Glutes']::text[], 'Barbell', 'Rest the bar on your upper back with knees slightly bent. Hinge at the hips until you feel the hamstrings load. Rise by squeezing your glutes.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e76', null, 'Cable Pull-through', 'Glutes', array['Hamstrings']::text[], 'Cable', 'Face away from a low pulley with the rope between your legs. Hinge back, then drive your hips forward to stand tall. Keep your spine neutral throughout.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e77', null, 'Glute Kickback Machine', 'Glutes', '{}'::text[], 'Machine', 'Brace your torso on the pad and place one foot on the platform. Push back until your hip fully extends. Return slowly without arching your back.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e78', null, 'Hip Adduction Machine', 'Adductors', '{}'::text[], 'Machine', 'Sit with the pads on the inside of your thighs. Squeeze your legs together. Open slowly to a comfortable stretch.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e79', null, 'Hanging Leg Raise', 'Core', '{}'::text[], 'Bodyweight', 'Hang from the bar with your shoulders active. Raise your legs by curling your pelvis up. Lower slowly without swinging.', false) on conflict (id) do nothing;
insert into public.exercises (id, user_id, nome, grupo_primario, grupos_secundarios, equipamento, instrucoes, is_custom) values ('e80', null, 'Ab Wheel Rollout', 'Core', array['Shoulders']::text[], 'Bodyweight', 'Kneel holding the wheel under your shoulders with your ribs down. Roll out as far as you can hold the brace. Pull back using your abs.', false) on conflict (id) do nothing;
